# --- Positive: DB-6 revision identity / history -----------------------------


def test_new_revision_down_revision_is_b34f8c1a9d27():
    revision_file = _new_revision_file()
    namespace: dict = {}
    exec(compile(open(revision_file).read(), revision_file, "exec"), namespace)
    assert namespace["revision"] == NEW_REVISION
    assert namespace["down_revision"] == PRE_REVISION


def test_alembic_history_shows_a_single_linear_head():
    script = ScriptDirectory.from_config(_cfg())
    assert len(script.get_heads()) == 1
    assert script.get_heads()[0] == CURRENT_HEAD


# --- Positive: DB-6 four new tables + four new columns ----------------------


def test_upgrade_head_creates_all_four_tables():
    assert {
        "page_access",
        "page_access_overrides",
        "page_access_publications",
        "admin_audit_events",
    } <= _table_names()


def test_page_access_columns_match_documented_types():
    columns = _columns("page_access")
    assert columns["page_id"]["nullable"] is False
    assert columns["role"]["nullable"] is False
    assert columns["level"]["nullable"] is False


def test_page_access_overrides_has_expected_fks_and_nullability():
    engine = create_engine(get_settings().database_url)
    try:
        insp = inspect(engine)
        fks = {fk["constrained_columns"][0]: fk["options"].get("ondelete") for fk in insp.get_foreign_keys("page_access_overrides")}
        assert fks.get("user_id") == "CASCADE"
        assert fks.get("granted_by") == "SET NULL"
    finally:
        engine.dispose()

    columns = _columns("page_access_overrides")
    assert columns["reason"]["nullable"] is False
    assert columns["expires_at"]["nullable"] is True
    assert columns["granted_by"]["nullable"] is True


def test_upgrade_head_adds_last_sign_in_at_and_admin_profile_columns():
    users_columns = _columns("users")
    assert users_columns["last_sign_in_at"]["nullable"] is True

    admin_columns = _columns("admin_profiles")
    assert admin_columns["department"]["nullable"] is True
    assert admin_columns["start_date"]["nullable"] is True
    assert admin_columns["address"]["nullable"] is True


def test_page_id_varchar_length_accommodates_every_known_page_id():
    columns = _columns("page_access")
    max_len = max(len(p) for p in PAGE_IDS)
    assert columns["page_id"]["type"].length >= max_len
    assert columns["page_id"]["type"].length == 64


