def test_seed_has_exactly_55_rows():
    assert len(_page_access_rows()) == 55


def test_seed_role_counts_match_b1_matrix():
    rows = _page_access_rows()
    counts: dict[str, int] = {}
    for _, role, _ in rows:
        counts[role] = counts.get(role, 0) + 1
    assert counts == {"RM": 7, "MOBO": 10, "PC": 10, "COMPLIANCE": 12, "ADMIN": 16}
    assert "PM" not in counts


def test_seed_level_counts_match_b1_matrix():
    rows = _page_access_rows()
    counts: dict[str, int] = {}
    for _, _, level in rows:
        counts[level] = counts.get(level, 0) + 1
    assert counts == {"edit": 30, "view": 25}


def test_admin_has_sixteen_edit_rows_one_per_page():
    rows = [(p, lvl) for p, role, lvl in _page_access_rows() if role == "ADMIN"]
    assert len(rows) == 16
    assert all(lvl == "edit" for _, lvl in rows)
    assert {p for p, _ in rows} == PAGE_IDS


def test_seed_matches_expected_matrix_cell_for_cell():
    actual = {(page_id, role): level for page_id, role, level in _page_access_rows()}
    assert actual == EXPECTED_MATRIX


# --- Negative: DB-7 deliberate exceptions + integrity -----------------------


def test_pm_has_zero_rows():
    assert all(role != "PM" for _, role, _ in _page_access_rows())


def test_pc_post_trade_allocation_is_view_not_edit():
    actual = {(p, r): lvl for p, r, lvl in _page_access_rows()}
    assert actual[("mobo.post-trade-allocation", "PC")] == "view"


def test_monthly_reports_narrows_rm_and_mobo_to_view_while_pc_keeps_edit():
    actual = {(p, r): lvl for p, r, lvl in _page_access_rows()}
    assert actual[("shared.monthly-reports", "RM")] == "view"
    assert actual[("shared.monthly-reports", "MOBO")] == "view"
    assert actual[("shared.monthly-reports", "PC")] == "edit"


def test_no_seeded_page_id_falls_outside_the_sixteen_known_ids():
    seeded_ids = {p for p, _, _ in _page_access_rows()}
    assert seeded_ids <= PAGE_IDS
    # No fictional catalog path literal (e.g. "/rm/dashboard") survived the rename map.
    assert not any(p.startswith("/") for p in seeded_ids)


def test_no_seeded_role_falls_outside_admin_role_values():
    seeded_roles = {r for _, r, _ in _page_access_rows()}
    assert seeded_roles <= ADMIN_ROLES


def test_reexecuting_the_seed_raises_integrity_error_on_unique_constraint():
    engine = create_engine(get_settings().database_url)
    try:
        with engine.begin() as conn:
            with pytest.raises(IntegrityError):
                conn.execute(
                    text(
                        "INSERT INTO page_access (page_id, role, level) VALUES "
                        "('rm.client-info', 'RM', 'edit')"
                    )
                )
    finally:
        engine.dispose()


def test_downgrade_drops_all_four_tables_and_all_four_columns():
    command.downgrade(_cfg(), PRE_REVISION)

    assert not (
        {"page_access", "page_access_overrides", "page_access_publications", "admin_audit_events"}
        & _table_names()
    )

    users_columns = _columns("users").keys()
    assert "last_sign_in_at" not in users_columns

    admin_columns = _columns("admin_profiles").keys()
    assert "department" not in admin_columns
    assert "start_date" not in admin_columns
    assert "address" not in admin_columns


# --- Invariants --------------------------------------------------------------


def test_no_pre_existing_table_or_column_is_touched():
    users_columns = _columns("users")
    assert {"id", "firebase_uid", "email", "portal"} <= users_columns.keys()


def test_upgrade_downgrade_upgrade_cycle_is_idempotent_and_reseeds():
    command.downgrade(_cfg(), PRE_REVISION)
    command.upgrade(_cfg(), "head")

    assert "page_access" in _table_names()
    assert len(_page_access_rows()) == 55


